from pathlib import Path
import datetime,json,hashlib
out=Path('.contexto/avaliacoes-ia-2026-10-16/acessibilidade')
files=sorted(out.glob('complementar-*.png'),key=lambda p:p.stat().st_mtime)
entries=[{'file':p.name,'modified_utc':datetime.datetime.fromtimestamp(p.stat().st_mtime,datetime.timezone.utc).isoformat(),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in files]
r={'agent':'avaliacao_ia_acessibilidade','type':'IA técnica, não participante humano','url':'https://luccalck.github.io/desafio-arcade/','displayed_version':'0.7.0','displayed_sha':'e9dd28c','first_capture_utc':entries[0]['modified_utc'],'last_capture_utc':entries[-1]['modified_utc'],'capture_span_seconds':round(files[-1].stat().st_mtime-files[0].stat().st_mtime,3),'script_clock_policy':'time.monotonic(); while elapsed<182; interação por varredura Tab/Shift+Tab e tentativas registradas; não sleep isolado','lost_action_log':True,'automation_errors':['Primeira tentativa interrompida por seletores visuais errados','Complementar chegou à serialização final e falhou: TypeError Object of type Response is not JSON serializable. Log em memória não preservado. Não é bug do jogo.'],'screenshots':entries}
(out/'sessao-complementar-metadados.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8')
p=out/'RELATORIO.md';s=p.read_text(encoding='utf-8-sig');s=s.replace('com ações e horários em sessao-complementar.json','até a etapa final de serialização. A gravação do log completo falhou porque uma ação devolveu objeto Response não serializável; o log em memória foi perdido. sessao-complementar-metadados.json preserva o inventário e timestamps das capturas, não recria ações perdidas');s=s.replace('ações e foco registrados no JSON principal','acionado pelo script; sem log completo persistido, não se declara resultado de foco desse link');s=s.replace('medição de largura no JSON','a medição de largura ocorreu em memória e foi perdida com o log; não se declara resultado numérico');s+='\n\nIntervalo entre primeira e última captura da execução complementar: '+str(r['capture_span_seconds'])+' segundos. Este intervalo é evidência de duração das capturas; as limitações de cobertura e a perda do log acima permanecem.\n';p.write_text(s,encoding='utf-8')
manifest=[]
for p in sorted(out.iterdir()):
 if p.is_file() and p.name!='manifesto.json':manifest.append({'file':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(out/'manifesto.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'screenshots':len(entries),'capture_span_seconds':r['capture_span_seconds'],'files':len(manifest)}))
